static const schema::RpcSchema& rpc_of(const char* cls, const char* name) {
    const schema::RpcSchema* r = schema_named(cls).rpc(name);
    if (!r) { std::printf("  [FAIL] no RPC %s on %s\n", name, cls); std::exit(2); }
    return *r;
}

static const char* class_of(const std::string& rpc) {
    return rpc == "ServerInteractWithInteractableComponent" ? "PlayerPawn_C" : "AoCPlayerControllerBP_C";
}

static std::optional<RpcCall> read_call(const schema::RpcSchema& rpc, const Bits& bits) {
    return with_exact(bits, [&](const uint8_t* d, size_t, size_t n) -> std::optional<RpcCall> {
        size_t pos = 0;
        auto p = read_rpc_params(rpc, d, n, pos, {});
        if (!p) return std::nullopt;
        RpcCall c;
        c.rpc = &rpc;
        c.params = std::move(*p);
        c.decoded = true;
        c.param_bits = n;
        return c;
    });
}

static std::optional<Bits> write_call(const schema::RpcSchema& rpc, const RpcParams& params) {
    BunchWriter w;
    bool failed = false;
    write_rpc_params(rpc, params, w, {}, &failed);
    if (failed) return std::nullopt;
    return Bits(w);
}
// C_Y_B and CoA

/// The call's typed form built again and written.
static std::optional<Bits> rebuild(const RpcCall& call) {
    const schema::RpcSchema& rpc = *call.rpc;
    const std::string name = rpc.name;
    std::optional<RpcParams> p;
    if (name == "ServerInteractWithInteractableComponent") {
        if (auto r = parse_interact_request(call)) p = interact_params(rpc, *r);
    } else if (name == "ServerHandleVendorPurchase") {
        if (auto r = parse_vendor_purchase(call)) p = vendor_purchase_params(rpc, *r);
    } else if (name == "ServerHandleVendorTransaction") {
        if (auto r = parse_vendor_transaction(call)) p = vendor_transaction_params(rpc, *r);
    } else if (name == "ClientOpenVendor") {
        if (auto r = parse_open_vendor(call)) p = open_vendor_params(rpc, r->merch_set, r->vendor);
    } else if (name == "ServerGetNodeTaxTable") {
        if (auto r = parse_node_tax_request(call)) p = node_tax_request_params(rpc, *r);
    } else if (name == "ClientSetNodeTaxTable") {
        if (auto r = parse_node_tax_table(call)) p = node_tax_table_params(rpc, *r);
    }
    if (!p) return std::nullopt;
    return write_call(rpc, *p);
}

/// The typed form of a call as text: what two payloads mean (a parameter sent at its default value reads as the value, one left out as
/// nothing: the same meaning, so the hostile checks compare this, not the parameter maps).
static std::string typed(const RpcCall& call) {
    const std::string name = call.rpc->name;
    // (an object with ObjectId 0 is a null object whatever its other words say: rpc.h sends it as the default)
    const auto g = [](const emit::FIntrepidNetworkGUID& id) { return id.ObjectId == 0 ? std::string("null") : guid_words(id); };
    std::string s;
    if (name == "ServerInteractWithInteractableComponent") {
        const auto r = parse_interact_request(call);
        if (!r) return "?";
        s = g(r->interactable) + "/" + snum(r->counter) + "/" + num(r->zone);
    } else if (name == "ServerHandleVendorPurchase") {
        const auto r = parse_vendor_purchase(call);
        if (!r) return "?";
        s = snum(r->vendor);
        for (const VendorCartItem& i : r->items)
            s += "|" + snum(i.item_record) + ":" + snum(i.quantity) + ":" + (i.optional_a ? snum(*i.optional_a) : "-") + ":" + (i.optional_b ? snum(*i.optional_b) : "-");
    } else if (name == "ServerHandleVendorTransaction") {
        const auto r = parse_vendor_transaction(call);
        if (!r) return "?";
        s = snum(r->vendor) + "/" + num(r->operation);
        for (const GuidValue& i : r->instances) s += "|" + num(i.a) + "," + num(i.b) + "," + num(i.c) + "," + num(i.d);
    } else if (name == "ClientOpenVendor") {
        const auto r = parse_open_vendor(call);
        if (!r) return "?";
        s = snum(r->merch_set) + "/" + g(r->vendor);
    } else if (name == "ServerGetNodeTaxTable") {
        const auto r = parse_node_tax_request(call);
        if (!r) return "?";
        s = snum(*r);
    } else if (name == "ClientSetNodeTaxTable") {
        const auto r = parse_node_tax_table(call);
        if (!r) return "?";
        s = snum(r->node);
        for (const NodeTaxEntry& e : r->entries) {
            // (floats by their bits: a NaN of a mutated payload is not equal to itself)
            s += "|" + e.tag + ":" + snum(e.details) + ":" + snum(e.flat_tax) + ":" + num(std::bit_cast<uint32_t>(e.tax_percent)) + ":" +
                 num(std::bit_cast<uint32_t>(e.owning_node_percent)) + ":" + (e.flag_a ? "1" : "0") + (e.flag_b ? "1" : "0");
        }
    }
    return s;
}

static void test_captured_calls() {
    std::printf("the captured vendor calls: read, typed, written back\n");
    int n = 0;
    for (const cap::Call* table : {cap::kClient, cap::kServer}) {
        const size_t count = table == cap::kClient ? std::size(cap::kClient) : std::size(cap::kServer);
        for (size_t i = 0; i < count; ++i) {
            const cap::Call& c = table[i];
            const Bits bits = bits_of_hex(c.hex, c.bits);
            const auto call = read_call(rpc_of(class_of(c.rpc), c.rpc), bits);
            const std::string what = std::string(c.source) + " " + c.rpc;
            CHECK(call.has_value(), (what + " reads to its last bit").c_str());
            if (!call) continue;
            const auto back = rebuild(*call);
            CHECK(back.has_value() && *back == bits, (what + " is written back to the same bits").c_str());
            ++n;
        }
    }
    CHECK(n == 10, "ten captured calls");
}

static const RpcCall& captured(size_t index, std::optional<RpcCall>& hold) {
    const cap::Call& c = cap::kClient[index];
    hold = read_call(rpc_of(class_of(c.rpc), c.rpc), bits_of_hex(c.hex, c.bits));
    if (!hold) { std::printf("  [FAIL] %s does not read\n", c.source); std::exit(2); }
    return *hold;
}

static void test_values() {
    std::printf("what the captured calls hold\n");
    std::optional<RpcCall> h;
    {
        const auto r = parse_interact_request(captured(0, h));
        CHECK(r.has_value(), "the interaction parses");
        if (r) {
            CHECK(r->interactable.ObjectId != 0 && (r->interactable.ObjectId & 1) == 0, "it names an object (an even ObjectId)");
            CHECK(r->zone == 0, "the zone is the default");
        }
    }
    {
        const auto r = parse_vendor_purchase(captured(1, h));
        CHECK(r && r->items.size() == 1 && r->items[0].quantity == 1 && !r->items[0].optional_a && !r->items[0].optional_b, "capture 863: one item, quantity 1, no optionals");
        CHECK(r && r->vendor != 0, "capture 863: a vendor guid");
        const auto t = parse_vendor_transaction(captured(4, h));
        CHECK(t && t->vendor == r->vendor && t->instances.size() == 1, "capture 716's sale names the same vendor and one instance");
    }
    {
        const auto r = parse_vendor_purchase(captured(2, h));
        CHECK(r && r->items.size() == 1 && r->items[0].quantity == 1 && r->items[0].optional_a && !r->items[0].optional_b, "capture 1531: one item, the first optional set");
    }
    {
        const auto r = parse_vendor_purchase(captured(3, h));
        CHECK(r && r->items.size() == 6, "capture 1536: six items");
        bool all_one = r != std::nullopt;
        for (size_t i = 0; r && i < r->items.size(); ++i) all_one = all_one && r->items[i].quantity >= 1 && !r->items[i].optional_a && !r->items[i].optional_b;
        CHECK(all_one, "capture 1536: every item a positive quantity with no optionals");
    }
    {
        std::optional<RpcCall> ho;
        const cap::Call& c = cap::kServer[0];
        const auto call = read_call(rpc_of(class_of(c.rpc), c.rpc), bits_of_hex(c.hex, c.bits));
        const auto o = call ? parse_open_vendor(*call) : std::nullopt;
        const auto buy = parse_vendor_purchase(captured(1, h));
        CHECK(o && buy && o->merch_set == buy->vendor, "ClientOpenVendor's MerchSetId is the VendorDef the purchase names");
        CHECK(o && o->vendor.ObjectId != 0, "ClientOpenVendor names the NPC");
    }
}
