static std::optional<NodeTaxDetails> captured_table(size_t server_index) {
    const cap::Call& c = cap::kServer[server_index];
    const auto call = read_call(rpc_of(class_of(c.rpc), c.rpc), bits_of_hex(c.hex, c.bits));
    return call ? parse_node_tax_table(*call) : std::nullopt;
}

static void test_tax_table_values() {
    std::printf("what the captured tax tables hold\n");
    std::optional<RpcCall> h;
    const auto ask716 = parse_node_tax_request(captured(5, h));
    const auto ask1536 = parse_node_tax_request(captured(6, h));
    CHECK(ask716 && ask1536 && *ask716 != 0 && *ask1536 != 0 && *ask716 != *ask1536, "both vendor windows ask for a node (two different, non-zero guids)");
    const auto t716 = captured_table(1);
    const auto t1536 = captured_table(2);
    CHECK(t716 && t1536, "both tables parse");
    if (!t716 || !t1536) return;
    CHECK(t716->node == *ask716 && t1536->node == *ask1536, "each table's NodeGuid is the node the window asked for");
    CHECK(t716->entries.size() == 78 && t1536->entries.size() == 78, "78 entries each");
    bool same_tags = t716->entries.size() == t1536->entries.size();
    bool one_record = true, sorted_unique = true, flat_zero = true, floats_sane = true;
    for (size_t i = 0; same_tags && i < t716->entries.size(); ++i) {
        const NodeTaxEntry& a = t716->entries[i];
        const NodeTaxEntry& b = t1536->entries[i];
        same_tags = same_tags && a.tag == b.tag;
        one_record = one_record && a.details == t716->entries[0].details && b.details == t716->entries[0].details;
        for (size_t j = 0; j < i; ++j) sorted_unique = sorted_unique && t716->entries[j].tag != a.tag;
        flat_zero = flat_zero && a.flat_tax == 0 && b.flat_tax == 0;
        floats_sane = floats_sane && a.tax_percent >= 0 && a.tax_percent <= 1 && a.owning_node_percent >= 0 && a.owning_node_percent <= 1 &&
                      b.tax_percent >= 0 && b.tax_percent <= 1 && b.owning_node_percent >= 0 && b.owning_node_percent <= 1;
    }
    CHECK(same_tags && t716->entries[0].tag == "NodeTax", "the two tables list the same tags, from \"NodeTax\" on");
    CHECK(one_record && t716->entries[0].details != 0, "every entry names the same TaxDetails record");
    CHECK(sorted_unique, "the tags are unique");
    CHECK(flat_zero && floats_sane, "flat taxes are 0 and the percents are fractions");
    // 716's node had its owners' taxes (the bools set, percents below the default), 1536's the defaults
    size_t changed716 = 0, changed1536 = 0;
    for (const NodeTaxEntry& e : t716->entries) changed716 += (e.tax_percent != 0.5f);
    for (const NodeTaxEntry& e : t1536->entries) changed1536 += (e.tax_percent != 0.5f);
    CHECK(changed716 > 20 && changed1536 == 0, "capture 716's node has taxes of its own (more than 20 entries off the 0.5 default), 1536's has none");
}

static VendorPurchaseCart cart_of(size_t n) {
    VendorPurchaseCart c;
    c.vendor = 0x5429e4906c3c0002;
    for (size_t i = 0; i < n; ++i) c.items.push_back({static_cast<int64_t>(0x5429e6b1eef80000ull + i), static_cast<int32_t>(1 + i % 5), std::nullopt, std::nullopt});
    return c;
}

static void test_limits() {
    std::printf("limits\n");
    {
        BunchWriter w;
        CHECK(write_vendor_purchase_cart(w, cart_of(kMaxVendorCartItems)), "a cart of 255 items is written");
        const Bits b(w);
        const auto back = with_exact(b, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorPurchaseCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_purchase_cart(r);
        });
        CHECK(back && *back == cart_of(kMaxVendorCartItems), "and reads back equal");
        BunchWriter w2;
        CHECK(!write_vendor_purchase_cart(w2, cart_of(kMaxVendorCartItems + 1)), "a cart of 256 is refused by the writer");
    }
    {
        VendorPurchaseCart c = cart_of(2);
        c.items[0].optional_a = -5;
        c.items[1].optional_b = 7;
        BunchWriter w;
        write_vendor_purchase_cart(w, c);
        const Bits b(w);
        const auto back = with_exact(b, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorPurchaseCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_purchase_cart(r);
        });
        CHECK(back && *back == c, "optionals round-trip, with their values");
        // a flag above 1
        Bits bad = b;
        bad.set(64 + 32 + 64 + 32, 2, 32);   // the first item's first flag: 2
        const auto refused = with_exact(bad, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorPurchaseCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_purchase_cart(r);
        });
        CHECK(!refused, "an optional flag of 2 is refused");
        Bits neg = b;
        neg.set(64, 0xFFFFFFFFu, 32);   // a count of -1
        const auto refused2 = with_exact(neg, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorPurchaseCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_purchase_cart(r);
        });
        CHECK(!refused2, "a negative count is refused");
        Bits big = b;
        big.set(64, 200, 32);   // 200 items, bits for two
        const auto refused3 = with_exact(big, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorPurchaseCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_purchase_cart(r);
        });
        CHECK(!refused3, "a count the bits cannot hold is refused");
    }
    {
        VendorTransactionCart t;
        t.vendor = 99;
        t.operation = 1;
        for (uint32_t i = 0; i < 3; ++i) t.instances.push_back({i + 1, 2, 3, 4});
        BunchWriter w;
        CHECK(write_vendor_transaction_cart(w, t), "a transaction cart is written");
        const Bits b(w);
        const auto back = with_exact(b, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<VendorTransactionCart> {
            PacketReader r(d, bytes, n);
            return read_vendor_transaction_cart(r);
        });
        CHECK(back && *back == t, "and reads back equal");
        t.instances.assign(kMaxVendorTransactionItems + 1, GuidValue{1, 2, 3, 4});
        BunchWriter w2;
        CHECK(!write_vendor_transaction_cart(w2, t), "256 instances are refused by the writer");
    }
    // the tax table
    {
        const auto read_back = [](const Bits& b) {
            return with_exact(b, [](const uint8_t* d, size_t bytes, size_t n) -> std::optional<NodeTaxDetails> {
                PacketReader r(d, bytes, n);
                return read_node_tax_details(r);
            });
        };
        NodeTaxDetails t;
        t.node = 0x62d025765679ll;
        t.entries.push_back({"NodeTax", 6064632157081894912ll, 0, 0.1f, 0.857f, true, true});
        t.entries.push_back({"NodeTax.GoodsTax.MarketplaceTax", 6064632157081894912ll, 7, 0.0f, 1.0f, false, false});
        t.entries.push_back({"", 5, -3, 1.0f, 0.5f, false, true});   // an empty tag: SaveNum 0
        BunchWriter w;
        CHECK(write_node_tax_details(w, t), "a tax table is written");
        const Bits b(w);
        CHECK(b.size() == 64 + 32 + (32 + 8 * 8 + 64 + 5 * 32) + (32 + 8 * 32 + 64 + 5 * 32) + (32 + 64 + 5 * 32), "its size is the layout's: 64, 32, and per entry 32 + 8 per character with the NUL + 64 + 5 * 32");
        const auto back = read_back(b);
        CHECK(back && *back == t, "and reads back equal");
        // an empty table and a node of 0
        NodeTaxDetails empty;
        BunchWriter we;
        write_node_tax_details(we, empty);
        const auto eback = read_back(Bits(we));
        CHECK(Bits(we).size() == 96 && eback && *eback == empty, "an empty table is 96 bits and round-trips");
        // the writer refuses what the reader would
        NodeTaxDetails many;
        many.entries.assign(kMaxNodeTaxEntries + 1, t.entries[0]);
        BunchWriter wm;
        CHECK(!write_node_tax_details(wm, many), "513 entries are refused by the writer");
        many.entries.resize(kMaxNodeTaxEntries);
        BunchWriter wm2;
        CHECK(write_node_tax_details(wm2, many) && read_back(Bits(wm2)) == many, "512 entries round-trip");
        NodeTaxDetails nul = t;
        nul.entries[0].tag = std::string("Node") + '\0' + "Tax";
        BunchWriter wn;
        CHECK(!write_node_tax_details(wn, nul), "a tag with a NUL inside is refused by the writer");
        NodeTaxDetails wide = t;
        wide.entries[0].tag = "Node\xe9Tax";
        BunchWriter ww;
        CHECK(!write_node_tax_details(ww, wide), "a tag with a non-ASCII byte is refused by the writer");
        NodeTaxDetails longtag = t;
        longtag.entries[0].tag.assign(kMaxNodeTaxTagChars, 'a');
        BunchWriter wl;
        CHECK(write_node_tax_details(wl, longtag) && read_back(Bits(wl)) == longtag, "a tag of 255 characters round-trips");
        longtag.entries[0].tag.assign(kMaxNodeTaxTagChars + 1, 'a');
        BunchWriter wl2;
        CHECK(!write_node_tax_details(wl2, longtag), "one of 256 is refused by the writer");
        // the reader's refusals
        Bits neg = b;
        neg.set(64, 0xFFFFFFFFu, 32);
        CHECK(!read_back(neg), "a negative entry count is refused");
        Bits big = b;
        big.set(64, 400, 32);
        CHECK(!read_back(big), "a count the bits cannot hold is refused");
        Bits utf16 = b;
        utf16.set(96, static_cast<uint32_t>(-8), 32);   // the first tag's SaveNum: negative, a UTF-16 string
        CHECK(!read_back(utf16), "a UTF-16 tag (a negative SaveNum) is refused");
        Bits longer = b;
        longer.set(96, 300, 32);
        CHECK(!read_back(longer), "a SaveNum above 256 is refused");
        Bits no_nul = b;
        no_nul.set(96 + 32 + 8 * 7, 'x', 8);   // the first tag's NUL replaced
        CHECK(!read_back(no_nul), "a tag that does not end in a NUL is refused");
        Bits flag = b;
        flag.set(96 + 32 + 8 * 8 + 64 + 3 * 32, 2, 32);   // the first entry's first bool: 2
        CHECK(!read_back(flag), "a bool of 2 is refused");
        CHECK(!read_back(b.slice(0, b.size() - 8)), "a table one byte short is refused");
    }
}

static void test_hostile() {
    std::printf("hostile input\n");
    struct Seed { const schema::RpcSchema* rpc; Bits bits; };
    std::vector<Seed> seeds;
    for (const cap::Call* table : {cap::kClient, cap::kServer}) {
        const size_t count = table == cap::kClient ? std::size(cap::kClient) : std::size(cap::kServer);
        for (size_t i = 0; i < count; ++i) seeds.push_back({&rpc_of(class_of(table[i].rpc), table[i].rpc), bits_of_hex(table[i].hex, table[i].bits)});
    }
    size_t truncations = 0, accepted = 0, mismatched = 0;
    for (const Seed& s : seeds) {
        // (the 54,537-bit tax tables: every 61st cut and the last 200, or the sweep would be quadratic in the table)
        for (size_t cut = 0; cut < s.bits.size(); cut += (s.bits.size() > 4096 && cut + 200 < s.bits.size()) ? 61 : 1) {
            ++truncations;
            const auto call = read_call(*s.rpc, s.bits.slice(0, cut));
            if (!call) continue;
            ++accepted;
            const auto back = rebuild(*call);
            if (back) {
                const auto again = read_call(*s.rpc, *back);
                if (!again || typed(*again) != typed(*call)) ++mismatched;
            }
        }
    }
    CHECK(truncations > 1000, "every truncation of every captured call was tried");
    CHECK(mismatched == 0, "whatever read, wrote back to a payload that reads equal");
    (void)accepted;
    Rng rng(0x7e1d0e5);
    size_t fuzzed = 0, bad = 0;
    for (int round = 0; round < 4000; ++round) {
        const Seed& s = seeds[rng.below(seeds.size())];
        Bits b = s.bits;
        const int mode = static_cast<int>(rng.below(4));
        if (mode == 0) {
            for (int k = 0, n = 1 + static_cast<int>(rng.below(4)); k < n; ++k) { const size_t at = rng.below(b.size()); b.b[at] = !b.b[at]; }
        } else if (mode == 1) {
            b = b.slice(0, 1 + rng.below(b.size()));
        } else if (mode == 2) {
            for (int k = 0, n = 1 + static_cast<int>(rng.below(300)); k < n; ++k) b.append(rng.next() & 1, 1);
        } else {
            const size_t at = rng.below(b.size() - 32);
            b.set(at, rng.below(4) == 0 ? 0xFFFFFFFFu : rng.next() & 0xFFFFu, 32);
        }
        ++fuzzed;
        const auto call = read_call(*s.rpc, b);
        if (!call) continue;
        const auto back = rebuild(*call);
        if (!back) continue;
        const auto again = read_call(*s.rpc, *back);
        if (!again || typed(*again) != typed(*call)) {
            if (++bad <= 3) std::printf("    mismatch: %s mode %d, %zu bits, again %s\n", s.rpc->name, mode, b.size(), again ? "differs" : "does not read");
        }
    }
    CHECK(fuzzed == 4000 && bad == 0, "a seeded fuzz of 4,000 mutations: nothing crashes, and what reads writes back equal");
}

